{
     "title": "CSCI-559: Seminar in Systems - Orientation Companion",
     "learningObjectives": [
       "Define the four practice groups of the Secure Software Development Framework and their roles in secure development.",
       "Explain how cryptographic standards, modes of operation, and key management collectively support confidentiality, integrity, and authenticity.",
       "Apply a practical analysis checklist to evaluate system security requirements, trust boundaries, and residual risk."
     ],
     "beats": [
       {
         "title": "Course Scope and Faculty Flexibility",
         "claim": "CSCI-559 is designed as a faculty pilot course to examine current topics in Systems without a fixed RIT syllabus.",
         "example": "Instructors select specific course instances belonging to the Distributed Systems, Architecture and Operating Systems, or Security cluster.",
         "visualDirection": "Display a flowchart showing three selectable cluster paths (Distributed Systems, Architecture and Operating Systems, Security) converging into a central 'Seminar in Systems' node.",
         "sourceIds": ["rit-csci-559"]
       },
       {
         "title": "Secure Software Development Framework Overview",
         "claim": "The Secure Software Development Framework groups practices into four practice groups: Prepare the Organization, Protect the Software, Produce Well-Secured Software, and Respond toV"
                    ,"example": "Prepare the Organization establishes people, processes, and technology for secure development.",
         "visualDirection": "Show a four-quadrant diagram labeling each practice group with its core function.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Prepare the Organization Practice",
         "claim": "Prepare the Organization establishes people, processes, and technology for secure development.",
         "example": "Teams define security policies and allocate resources before writing code.",
         "visualDirection": "Illustrate a checklist with three items: 'Define security policies', 'Allocate resources', 'Establish development processes'.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Protect the Software Practice",
         "claim": "Protect the Software prevents unauthorized access to code and development artifacts.",
         "example": "Repositories use role-based access control to restrict who can view or modify source files.",
         "visualDirection": "Draw a locked vault icon with three access levels: 'Read', 'Write', 'Admin' labeled around it.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Produce Well-Secured Software Practice",
         "claim": "Produce Well-Secured Software addresses security requirements, design, verification, and release.",
         "example": "Developers verify that security requirements are met before deploying the final software version.",
         "visualDirection": "Create a pipeline graphic showing 'Requirements' -> 'Design' -> 'Verification' -> 'Release' with checkmarks at each stage.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Respond to Vulnerabilities Practice",
         "claim": "Respond to Vulnerabilities identifies, analyzes, remediates, and learns from discovered weaknesses.",
         "example": "When a bug is found, the team patches the code and updates the security documentation.",
         "visualDirection": "Show a circular diagram with arrows labeled 'Identify', 'Analyze', 'Remediate', 'Learn' connecting back to 'Identify'.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Security Requirements and Reasoning",
         "claim": "Security requirements should be tracked throughout development, and security reasoning identifies assets, trust boundaries, threats, controls, evidence, residual risk, andresponsib"
                    ,"example": "A system tracks user authentication requirements from design through testing.",
         "visualDirection": "Display a table with columns: 'Asset', 'Trust Boundary', 'Threat', 'Control', 'Evidence', 'Residual Risk', 'Responsibility'.",
         "sourceIds": ["nist-ssdf"]
       },
       {
         "title": "Cryptographic Standards and Confidentiality",
         "claim": "Cryptographic standards define approved algorithms and parameters, and encryption supports confidentiality when keys and modes are used correctly.",
         "example": "AES-256 encryption protects data in transit when paired with a secure key exchange protocol.",
         "visualDirection": "Show a padlock icon with a key inside, labeled 'AES-256', and a shield icon labeled 'Confidentiality'.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Integrity, Authenticity, and Key Management",
         "claim": "Message authentication and digital signatures address integrity and authenticity in different ways, and key management covers generation, distribution, storage, use, rotation, rev"
                    ,"example": "Digital signatures verify that a message was sent by a specific sender without alteration.",
         "visualDirection": "Draw two side-by-side icons: a stamp icon labeled 'Digital Signature' and a key ring icon labeled 'Key Management'.",
         "sourceIds": ["nist-cryptographic-standards"]
       },
       {
         "title": "Modes of Operation and Side Channels",
         "claim": "Modes of operation define how a primitive processes data larger than one block, and security depends on the complete protocol and implementation, not only an algorithm name.",
         "example": "CBC mode processes data in blocks, but timing attacks can expose vulnerabilities if not implemented securely.",
         "visualDirection": "Show a block diagram with arrows showing data flowing through multiple blocks, labeled 'Mode of Operation'.",
         "sourceIds": ["nist-cryptographic-standards"]
       }
     ]
   }
